import {googlePriceQuestion} from './google-pricing.js';
export function initGooglePricing({market,node,api,getData,validate,begin,current,onQuery,onUse,notify}){
 const status=market.querySelector('#research-status'),output=market.querySelector('#automatic-prices'),button=market.querySelector('#research');
 button.onclick=async()=>{if(validate().length){notify('Corrige primero los datos de la ficha.',{type:'warning'});return;}const data=getData();if(!data.make||!data.name||!data.year){notify('Completa marca, modelo y año.',{type:'warning'});return;}const generation=begin(),question=googlePriceQuestion(data);onQuery();button.disabled=true;output.replaceChildren();status.textContent='La IA está preparando los tres precios para este vehículo…';try{const result=await api('admin/research','POST',data);if(generation!==current()||question!==googlePriceQuestion(getData()))return;status.textContent=result.notice;for(const group of result.valuation||[]){const grid=node('div','price-strategies');for(const scenario of group.scenarios){const card=node('article','price-strategy '+scenario.key),use=node('button','','Usar este precio');use.type='button';use.onclick=()=>onUse(scenario.price,group.currency);card.append(node('span','',scenario.label),node('strong','',(group.currency==='BOB'?'Bs ':'US$ ')+scenario.price.toLocaleString('en-US')),node('p','',scenario.reason),use);grid.append(card);}output.append(grid);}if(result.explanation){const detail=node('details'),summary=node('summary','','Por qué sugiere estos precios'),text=node('p','',result.explanation);detail.append(summary,text);output.append(detail);}}catch(e){if(generation===current())status.textContent=e.message;}finally{if(generation===current())button.disabled=false;}};
 return{reset(){}};
}
